-- Données de départ de la boutique : compte vendeuse unique et catégories « Lits ».
-- À lancer une fois après les migrations : psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f scripts/seed-boutique.sql
-- Idempotent : peut être rejoué sans créer de doublon. Aucun produit n'est créé : ajoutez les vôtres depuis /gestion.

SELECT setval(pg_get_serial_sequence('categories','id'), GREATEST((SELECT COALESCE(MAX("id"),0) FROM "categories"),1));
SELECT setval(pg_get_serial_sequence('brands','id'), GREATEST((SELECT COALESCE(MAX("id"),0) FROM "brands"),1));
SELECT setval(pg_get_serial_sequence('product_images','id'), GREATEST((SELECT COALESCE(MAX("id"),0) FROM "product_images"),1));
INSERT INTO "users" ("name","email","password_hash","role","status")
SELECT 'MyBigMarket','boutique@mybigmarket.ci','!compte-sans-connexion','seller','active'
WHERE NOT EXISTS (SELECT 1 FROM "users" WHERE "email"='boutique@mybigmarket.ci');
INSERT INTO "seller_profiles" ("user_id","university","city_china","verification_status")
SELECT u."id",'MyBigMarket','Abidjan','pending' FROM "users" u
WHERE u."email"='boutique@mybigmarket.ci' AND NOT EXISTS (SELECT 1 FROM "seller_profiles" sp WHERE sp."user_id"=u."id");
INSERT INTO "categories" ("name","slug","parent_id","description","sort_order","meta_title","meta_description","intro_text","body_text","faq")
VALUES ('Lits','lits',NULL,'Lits de toutes les tailles, du lit simple au lit 3 places, pour la chambre des enfants comme pour la chambre parentale.',1,'Lits à Abidjan : 1 place, 2 places, enfants, bois, métal | MyBigMarket','Lits 1 place, 2 places, 2,5 places et 3 places, lits enfants, superposés, pliables, en bois ou en métal. Livraison à Abidjan et en Côte d''Ivoire, paiement par mobile money.','Lits de toutes les tailles, du lit simple au lit 3 places, pour la chambre des enfants comme pour la chambre parentale.','Quelle taille de lit choisir ? Le lit 1 place (90 cm de large) convient à une personne seule ou à une chambre d''enfant. Le lit 2 places (140 cm) accueille deux personnes dans une chambre de taille moyenne. Les lits 2,5 places (160 cm) et 3 places (180 cm) offrent plus d''espace, à condition de prévoir la place autour du lit pour circuler.

Pensez à mesurer votre chambre et la porte d''entrée avant de commander. Le matelas se vend séparément, sauf pour les packs lit + matelas.

Chaque fiche indique les dimensions, la matière, la disponibilité à Abidjan ou le délai sur commande. Le paiement se fait par mobile money : Orange Money, MTN MoMo, Moov Money ou Wave.','[{"question": "Quelle taille de lit choisir ?", "answer": "1 place (90 cm) pour une personne ou un enfant, 2 places (140 cm) pour un couple dans une chambre moyenne, 2,5 places (160 cm) ou 3 places (180 cm) si vous voulez plus de confort et que la chambre est assez grande."}, {"question": "Le matelas est-il fourni avec le lit ?", "answer": "Non, sauf pour les packs lit + matelas. La fiche de chaque produit précise ce qui est inclus."}, {"question": "Comment payer ?", "answer": "Par mobile money : Orange Money, MTN MoMo, Moov Money ou Wave. Je vous envoie les instructions de paiement sur WhatsApp après votre commande."}, {"question": "Quel est le délai de livraison ?", "answer": "En stock à Abidjan : 24 à 72 h. Sur commande : le délai est indiqué sur la fiche et dans votre panier."}]'::jsonb)
ON CONFLICT ("slug") DO UPDATE SET "name"=EXCLUDED."name","parent_id"=EXCLUDED."parent_id","description"=EXCLUDED."description","sort_order"=EXCLUDED."sort_order","meta_title"=EXCLUDED."meta_title","meta_description"=EXCLUDED."meta_description","intro_text"=EXCLUDED."intro_text","body_text"=EXCLUDED."body_text","faq"=EXCLUDED."faq";
